<script setup lang="ts">
import {computed,inject,onMounted,ref,watch} from 'vue'
import {routeLocationKey} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {storeToday} from '../time'
import {dayBadges,secondsText,type MonthPage,type EmployeeMonth,type EffectiveDay} from '../attendanceMonth'
import AttendanceMonthGrid from '../components/AttendanceMonthGrid.vue'
import MyAttendanceCalendar from '../components/MyAttendanceCalendar.vue'
import AttendanceIntervalExceptions from '../components/AttendanceIntervalExceptions.vue'
import type {Position} from '../types'
const route=inject(routeLocationKey,null),requestedMonth=route?.query.attendanceMonth||route?.query.month
const {api,home,store,current,base,english,loading,busy,failure,load}=usePhasePage(),month=ref(typeof requestedMonth==='string'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(requestedMonth)?requestedMonth:storeToday().slice(0,7)),search=ref(''),position=ref(''),positions=ref<Position[]>([]),offset=ref(0),data=ref<MonthPage|null>(null),single=ref(''),view=ref('table'),selected=ref<{employee:EmployeeMonth;day:EffectiveDay}|null>(null),reviewNote=ref(''),targetEmployee=ref(typeof route?.query.employeeId==='string'?route.query.employeeId:'')
const en=computed(()=>english()),key=computed(()=>JSON.stringify([store.value,month.value,search.value,position.value,offset.value,targetEmployee.value])),loadedKey=ref(''),fresh=computed(()=>loadedKey.value===key.value),personal=computed(()=>data.value?.employees.find(e=>e.employeeId===single.value)||data.value?.employees[0])
watch([month,search,position],()=>{offset.value=0;data.value=null;selected.value=null})
function refresh(){selected.value=null;data.value=null;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month.value))return;const captured=key.value,client=api(),query=new URLSearchParams({month:month.value,search:search.value,limit:'30',offset:String(offset.value),...(position.value?{positionId:position.value}:{}),...(targetEmployee.value?{employeeId:targetEmployee.value}:{})});void load(()=>client.get<MonthPage>('/attendance-month?'+query),v=>{if(captured!==key.value)return;data.value=v;loadedKey.value=captured})}
async function evaluate(){if(!data.value?.canManage||busy.value||!fresh.value||!data.value.employees.length)return;const captured=key.value,shop=store.value,client=api(),body={month:month.value,employeeIds:data.value.employees.map(e=>e.employeeId)};busy.value=true;failure.value='';try{await client.put('/attendance-month/refresh',body);if(current()&&shop===store.value&&captured===key.value)refresh()}catch{if(current()&&shop===store.value)failure.value=en.value?'Update failed or permission denied. Retry updates only this displayed employee range.':'更新失败或无权操作；重试只更新当前页明确员工范围。'}finally{if(current()&&shop===store.value)busy.value=false}}
const canReview=computed(()=>!!selected.value&&!!home.value?.employeeManage&&selected.value.employee.employeeId!==home.value?.myself?.id&&(selected.value.day.issues.includes('WORKFORCE_MANAGER_ADMIN_REVIEW')?!!home.value?.headOffice:selected.value.day.issues.includes('CALENDAR_REVIEW_REQUIRED'))&&selected.value.day.issues.every(i=>['WORKFORCE_MANAGER_ADMIN_REVIEW','CALENDAR_REVIEW_REQUIRED','EVALUATION_REQUIRED'].includes(i)))
async function review(){if(!canReview.value||!selected.value||busy.value||!reviewNote.value.trim())return;const captured=key.value,shop=store.value,client=api(),{employee,day}=selected.value;busy.value=true;try{await client.put(`/attendance-days/${encodeURIComponent(day.sourceId)}/review`,{employeeId:employee.employeeId,companyId:day.snapshot.companyId,workDate:day.workDate,expectedVersion:day.version,sourceFingerprint:day.sourceFingerprint,note:reviewNote.value.trim()});if(current()&&shop===store.value&&captured===key.value)refresh()}catch{if(current()&&shop===store.value)failure.value=en.value?'Review failed or source changed. Reload this month.':'核准失败或来源已变化，请重新查询本月。'}finally{if(current()&&shop===store.value)busy.value=false}}
function choose(employee:EmployeeMonth,day:EffectiveDay){reviewNote.value='';selected.value={employee,day}}
function page(n:number){offset.value=Math.max(0,offset.value+n);refresh()}
onMounted(()=>{refresh();if(home.value?.employeeManage){const shop=store.value;void api().get<Position[]>('/positions').then(v=>{if(current()&&shop===store.value)positions.value=v}).catch(()=>{})}})
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{en?(home?.employeeManage?'Monthly attendance':'My attendance calendar'):(home?.employeeManage?'月度考勤':'我的考勤月历')}}</h2><RouterLink :to="base+'/leave-entitlements'">{{en?'Leave balance':'假期余额'}}</RouterLink><RouterLink :to="base+'/attendance-records'">{{en?'Clock records':'打卡明细'}}</RouterLink></header><nav v-if="home?.employeeManage" class="wf-subnav"><RouterLink :to="base+'/attendance'">{{en?'Monthly attendance':'月度考勤'}}</RouterLink><RouterLink :to="base+'/approvals'">{{en?'Review exceptions':'异常核准'}}</RouterLink><RouterLink :to="base+'/attendance-policy'">{{en?'Attendance policies':'考勤设置'}}</RouterLink></nav><form class="wf-filters" @submit.prevent="refresh"><label>{{en?'Month':'月份'}}<input v-model="month" type="month" required></label><label v-if="home?.employeeManage">{{en?'Employee name / number':'姓名 / 工号'}}<input v-model="search" maxlength="100"></label><label v-if="home?.employeeManage">{{en?'Position':'岗位'}}<select v-model="position"><option value="">{{en?'All':'全部'}}</option><option v-for="p in positions" :key="p.id" :value="p.id">{{p.name}}</option></select></label><button :disabled="loading||busy">{{en?'Load month':'查询本月'}}</button></form><button v-if="targetEmployee&&home?.employeeManage" type="button" :disabled="loading||busy" @click="targetEmployee='';offset=0;refresh()">{{en?'Show all employees':'显示所有员工'}}</button><p class="wf-hint">{{en?'Normal effective days are blank. Missing punches require review; they do not mean absence. Extra work and payable overtime are separate.':'正常有效日期留白；缺卡须核对，不直接认定缺勤。批准额外工作与计薪加班分别显示。'}}</p><p v-if="loading" role="status">{{en?'Loading…':'加载中…'}}</p><p v-if="failure" class="wf-error" role="alert">{{failure}}</p><button v-if="failure" :disabled="loading||busy" @click="refresh">{{en?'Retry query':'重试查询'}}</button><template v-if="data&&fresh&&!loading"><div v-if="data.canManage&&data.employees.length" class="wf-toolbar"><div class="wf-inline"><button :disabled="busy" @click="evaluate">{{en?'Update judgments for this page':'更新本页本月判定'}}</button><small>{{en?'Explicit range:':'明确范围：'}} {{data.employees.length}} {{en?'employees':'名员工'}}</small></div><label class="am-view">{{en?'View':'视图'}}<select v-model="view"><option value="table">{{en?'Employee grid':'员工月表'}}</option><option value="calendar">{{en?'Single employee calendar':'单人月历'}}</option></select></label></div><p v-if="!data.employees.length" class="wf-empty">{{en?'No employees in this range':'该范围暂无员工'}}</p><template v-else><div v-if="data.canManage&&view==='table'" class="am-desktop"><AttendanceMonthGrid :employees="data.employees" :english="en" @select="choose"/></div><div :class="{'am-mobile':data.canManage&&view==='table'}"><label v-if="data.canManage">{{en?'Employee':'员工'}}<select v-model="single"><option v-for="e in data.employees" :key="e.employeeId" :value="e.employeeId">{{e.name}} · {{e.employeeNo}}</option></select></label><MyAttendanceCalendar v-if="personal" :employee="personal" :english="en" @select="choose"/></div></template><footer v-if="data.canManage" class="wf-pagination"><button :disabled="offset===0||busy" @click="page(-30)">{{en?'Previous':'上一页'}}</button><span>{{offset+1}}–{{offset+data.employees.length}} / {{data.total}}</span><button :disabled="offset+data.employees.length>=data.total||busy" @click="page(30)">{{en?'Next':'下一页'}}</button></footer></template><section v-if="selected&&fresh" class="wf-source" aria-live="polite"><header class="wf-toolbar"><h3>{{selected.employee.name}} · {{selected.day.workDate}}</h3><button @click="selected=null">{{en?'Close':'关闭'}}</button></header><p>{{dayBadges(selected.day,en).join(' · ')||(selected.day.state==='not_applicable'?(en?'Hours not applicable':'工时不适用'):(en?'Normal — effective source':'正常，来源有效'))}}</p><dl class="wf-details"><dt>{{en?'Recognized work':'认定工时'}}</dt><dd>{{selected.day.mode==='contract'||selected.day.mode==='free'?(en?'N/A':'不适用'):secondsText(selected.day.workSeconds,en)}}</dd><dt>{{en?'Actual clock work':'实际打卡工时'}}</dt><dd>{{selected.day.actualSeconds==null?(en?'No actual clock source':'无实际打卡来源'):secondsText(selected.day.actualSeconds,en)}}</dd><dt>{{en?'Source':'来源'}}</dt><dd>{{selected.day.sourceType==='arrangement'?(en?'Work arrangement':'工作安排'):selected.day.sourceType==='actual'?(en?'Actual clock':'实际打卡'):(en?'Not applicable':'不适用')}} · v{{selected.day.version}}</dd></dl><form v-if="canReview" class="wf-section" @submit.prevent="review"><label>{{en?'Day review note':'当天核准备注'}}<input v-model="reviewNote" maxlength="500" required></label><button :disabled="busy" class="primary">{{en?'Confirm effective day source':'核准当天有效来源'}}</button></form><AttendanceIntervalExceptions v-if="selected.day.snapshot.timezone&&selected.day.snapshot.companyId" :key="selected.employee.employeeId+selected.day.workDate" :employee-id="selected.employee.employeeId" :date="selected.day.workDate" :timezone="String(selected.day.snapshot.timezone||'')" :company-id="String(selected.day.snapshot.companyId||'')" @saved="refresh"/></section></section></template>
<style scoped>.am-mobile{display:none}.am-view{margin:0;min-width:170px}@media(max-width:700px){.am-desktop{display:none}.am-mobile{display:block}}</style>
